window.kbPageData["views/entry/k-4fa49728ada827d8"] = {"key":"entry/k-4fa49728ada827d8","state":{"route":"entry/k-4fa49728ada827d8"},"node":{"id":"k-4fa49728ada827d8","mode":"k","title":"年均增速与累计增长倍数","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["按固定年均增速复利增长时，相同跨度的期末量与期初量之比相同"],"qs":["江苏 2024 C类 行测#129"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"年均增速是使基期量经过若干年等速复利增长后恰好达到期末量的等效年增长率。年均增速为 r 时，跨 n 个年度增长间隔的累计增长倍数为 (1+r)^n，即期末量除以基期量。","review":{"definition":"年均增速是使基期量经过若干年等速复利增长后恰好达到期末量的等效年增长率。年均增速为 r 时，跨 n 个年度增长间隔的累计增长倍数为 (1+r)^n，即期末量除以基期量。","explanation":"2020—2022年的三个同比增长间隔从2019年末算起。按解析给出的收入数据，这三年的累计增长倍数为2659÷2309。题设令2023—2025年每年按同一年均增速增长，从2022年末到2025年末也有三个增长间隔，因此可直接用2022年的2659亿元乘以同一倍数，得到约3062亿元，对应C项。","references":[],"evidence":"2022年和2019年我国游戏市场销售收入分别为2659和2309亿元","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 C类 行测#129":{"paper":"江苏 2024 C类 行测","n":129,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",27],"asrc":["02d6b49839583bdaf297.pdf",38],"card":"ef76858f5d258ce06a576a98","links":[{"id":"k-4fa49728ada827d8","role":"解题依据","why":"前后两段均为三年，因此可沿用前一段的累计增长倍数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4fa49728ada827d8":[["江苏 2024 C类 行测#129"]]}};
